import requests,re
from bs4 import BeautifulSoup
html=requests.get('https://www.ala.org/bbooks/frequentlychallengedbooks/top10/archive',headers={'User-Agent':'Mozilla/5.0'}).text
ids={'childrens':'75742','ya':'75743','classics':'75744','diverse':'75746'}
texts={}
for key,id_ in ids.items():
    m=re.search(rf'<div id="accordion-item-{id_}".*?<div class="clearfix text-formatted field field--name-field-body.*?field__item">(.*?)</div>\s*</div>',html,re.S)
    texts[key]=BeautifulSoup(m.group(1),'html.parser').get_text('\n')
books=['Melissa','The Absolutely True Diary of a Part-Time Indian','To Kill a Mockingbird','The Hate U Give','Beyond Magenta: Transgender Teens Speak Out','A Day in the Life of Marlon Bundo','Sex is a Funny Word','I Am Jazz','Drama','And Tango Makes Three','Thirteen Reasons Why','This One Summer','Two Boys Kissing','Looking for Alaska']
for b in books:
    present=[]
    for key,text in texts.items():
        norm=text.replace('George','Melissa')
        if b in norm or b.replace('The ','') in norm:
            present.append(key)
    print(b, present)
